<x-cms.app-layout title="Messages" section="messages">
    <section data-contact-inbox data-can-update="{{ auth()->user()->hasPermission('contact-messages.update') ? 'true' : 'false' }}" data-can-delete="{{ auth()->user()->hasPermission('contact-messages.delete') ? 'true' : 'false' }}" class="grid gap-6">
        <div><p class="text-sm text-cms-navy/55">Review website enquiries and move each conversation forward.</p><h2 class="mt-1 text-2xl font-bold">Contact inbox</h2></div>
        <div data-contact-notice class="hidden rounded-xl border p-4 text-sm"></div>
        <div class="grid min-h-[38rem] overflow-hidden rounded-2xl border border-cms-navy/8 bg-white/70 shadow-sm xl:grid-cols-[25rem_minmax(0,1fr)]">
            <div class="flex min-h-0 flex-col border-b border-cms-navy/8 xl:border-r xl:border-b-0">
                <div class="grid gap-3 border-b border-cms-navy/8 p-4"><input data-contact-search type="search" placeholder="Search name, email, subject…" class="h-11 rounded-xl border border-cms-navy/10 bg-white px-4 text-sm outline-none focus:border-cms-gold"><div class="grid grid-cols-3 gap-2"><select data-contact-status class="h-10 rounded-xl border border-cms-navy/10 bg-white px-2 text-xs"><option value="">All statuses</option><option value="new">New</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="spam">Spam</option></select><input data-contact-from type="date" aria-label="From date" class="h-10 rounded-xl border border-cms-navy/10 bg-white px-2 text-xs"><input data-contact-to type="date" aria-label="To date" class="h-10 rounded-xl border border-cms-navy/10 bg-white px-2 text-xs"></div></div>
                <div data-contact-list class="grid max-h-[34rem] min-h-0 overflow-y-auto"><p class="p-5 text-sm text-cms-navy/45">Loading messages…</p></div>
                <div class="flex items-center justify-between border-t border-cms-navy/8 p-4"><p data-contact-summary class="text-xs text-cms-navy/45"></p><div class="flex gap-2"><button data-contact-previous type="button" class="h-8 rounded-lg border bg-white px-2.5 text-xs disabled:opacity-35">Previous</button><button data-contact-next type="button" class="h-8 rounded-lg border bg-white px-2.5 text-xs disabled:opacity-35">Next</button></div></div>
            </div>
            <div data-contact-empty class="grid place-items-center p-10 text-center"><div><span class="mx-auto grid size-14 place-items-center rounded-2xl bg-cms-canvas text-xl text-cms-green">✉</span><h3 class="mt-4 font-bold">Choose a message</h3><p class="mt-2 text-sm text-cms-navy/45">Select an enquiry to read and manage it.</p></div></div>
            <article data-contact-detail class="hidden min-w-0 p-5 sm:p-7">
                <div class="flex flex-col justify-between gap-4 border-b border-cms-navy/8 pb-5 sm:flex-row sm:items-start"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><span data-contact-detail-status class="rounded-full px-2.5 py-1 text-xs font-bold"></span><span data-contact-detail-date class="text-xs text-cms-navy/40"></span></div><h3 data-contact-detail-subject class="mt-3 text-xl font-bold text-cms-navy"></h3><p data-contact-detail-sender class="mt-2 text-sm text-cms-navy/55"></p></div><button data-contact-delete type="button" class="hidden h-10 shrink-0 rounded-xl border border-red-200 bg-white px-4 text-xs font-bold text-red-700">Delete</button></div>
                <div class="grid gap-6 py-6 lg:grid-cols-[minmax(0,1fr)_18rem]"><div class="grid content-start gap-5"><div data-contact-detail-message class="whitespace-pre-wrap rounded-2xl bg-cms-canvas/55 p-5 text-sm leading-7 text-cms-navy"></div><div class="grid gap-2 text-sm"><a data-contact-detail-email class="font-semibold text-cms-green"></a><a data-contact-detail-phone class="font-semibold text-cms-green"></a><p data-contact-detail-company class="text-cms-navy/55"></p></div><details class="rounded-xl border border-cms-navy/8 p-4 text-xs text-cms-navy/45"><summary class="cursor-pointer font-bold text-cms-navy/60">Submission details</summary><p data-contact-detail-technical class="mt-3 break-all leading-5"></p></details></div>
                    <form data-contact-update-form class="grid content-start gap-4 rounded-2xl border border-cms-navy/8 bg-white p-5"><h4 class="font-bold">Workflow</h4><label class="grid gap-2"><span class="text-xs font-semibold">Status</span><select data-contact-detail-status-input class="h-11 rounded-xl border border-cms-navy/10 bg-white px-3"><option value="new">New</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="spam">Spam</option></select></label><label class="grid gap-2"><span class="text-xs font-semibold">Assigned to</span><select data-contact-detail-assignee class="h-11 rounded-xl border border-cms-navy/10 bg-white px-3"><option value="">Unassigned</option></select></label><label class="grid gap-2"><span class="text-xs font-semibold">Internal notes</span><textarea data-contact-detail-notes maxlength="10000" class="min-h-32 rounded-xl border border-cms-navy/10 bg-white p-3 text-sm" placeholder="Private notes for your team"></textarea></label><button data-contact-save class="h-11 rounded-xl bg-cms-green px-4 text-sm font-bold text-white">Save changes</button></form>
                </div>
            </article>
        </div>
    </section>
</x-cms.app-layout>
